function equipmentProfileDistance(item){const p=item.parameters||{};if(['asrs','stackerCrane'].includes(item.type))return Math.max(.1,(Math.max(1,Number(p.columns)||1)-1)*Math.max(.1,Number(p.columnPitch)||1.5));if(item.type==='conveyor'||item.type==='sorter')return Math.max(.1,Number(p.length)||5);if(['agv','amr','shuttle'].includes(item.type))return Math.max(.1,Number(p.shuttleDistance)||5);if(item.type==='forklift')return Math.max(.1,Number(p.travelDistance)||5);if(item.type==='lift')return Math.max(.1,Number(p.liftHeight)||3);if(item.type==='forkingDevice')return Math.max(.1,Number(p.strokeDistance)||1.5);return 0;}
