function renderCadEquipmentParameters(selectedId=selectedEquipment?.id){
  const items=layout.equipment.filter(item=>item.source?.origin==='dxf'&&item.reviewStatus==='approved'),counts={};
  const legacyConveyor=items.find(item=>item.type==='conveyor'&&(item.parameters?.cargoLength||item.parameters?.cargoWidth));if(!layout.cargoSpec)layout.cargoSpec={length:Number(legacyConveyor?.parameters?.cargoLength||1.2),width:Number(legacyConveyor?.parameters?.cargoWidth||.8)};ensureCargoSpecMm();
  for(const item of items){ensureDynamicParameters(item);applyAutomaticMotionDynamics(item);counts[item.type]=(counts[item.type]||0)+1;}
  const active=items.length>0;$('defaultEquipmentControls').hidden=active;$('dynamicEquipmentControls').hidden=!active;cadParameterSection.hidden=!active;
  const groups=Object.entries(Object.groupBy?Object.groupBy(items,item=>item.type):items.reduce((result,item)=>((result[item.type]??=[]).push(item),result),{}));
  cadParameterSection.innerHTML=active?`<h2>레이아웃 설비 파라미터</h2><details class="equipment-parameter-card selected" open><summary>공통 물류 규격</summary><label>물류 길이(mm)<span><input type="number" step="1" min="1" data-cargo-parameter="length" value="${layout.cargoSpec.length}"></span></label><label>물류 폭(mm)<span><input type="number" step="1" min="1" data-cargo-parameter="width" value="${layout.cargoSpec.width}"></span></label><label>물류 무게(kg)<span><input type="number" step="0.1" min="0.01" data-cargo-parameter="weight" value="${layout.cargoSpec.weight}"></span></label></details><p class="equipment-counts">${selectedId?'선택 설비의 파라미터가 펼쳐졌습니다 · ':''}${Object.entries(counts).map(([type,count])=>`${type.toUpperCase()} ${count}대`).join(' · ')}</p>`+groups.map(([type,equipment])=>`<div class="equipment-type-group"><h3>${type.toUpperCase()} <small>${equipment.length}대</small></h3>${equipment.map(item=>`<details class="equipment-parameter-card${item.id===selectedId?' selected':''}" data-parameter-card="${item.id}" ${item.id===selectedId?'open':''}><summary>${item.name}</summary>${parameterFieldsFor(item).map(field=>`<label>${field.label}<span><input type="number" step="0.1" ${field.min!==undefined?`min="${field.min}"`:''} ${field.max!==undefined?`max="${field.max}"`:''} ${field.readOnly?'readonly':''} data-equipment-id="${item.id}" data-parameter="${field.key}" value="${field.value}"></span></label>`).join('')}</details>`).join('')}</div>`).join(''):'';
  if(active){appendConveyorHandoverControls(items);appendForkParameterControls(items);appendAsrsBatchControls(items);appendSourceCargoControls(items);appendEquipmentMotionProfiles(items,selectedId);groupDependentParameterControls(items);appendCommonApplyControls(items);}
  if(selectedId)requestAnimationFrame(()=>cadParameterSection.querySelector(`[data-parameter-card="${CSS.escape(selectedId)}"]`)?.scrollIntoView({block:'nearest',behavior:'smooth'}));
}
