cadParameterSection.addEventListener('change',event=>{const enabled=event.target.closest('[data-fork-enabled]');if(enabled){const item=layout.equipment.find(entry=>entry.id===enabled.dataset.forkId);if(item){item.parameters??={};item.parameters.distributionEnabled=enabled.checked;resetEngine();renderCadEquipmentParameters(item.id);}return;}const common=event.target.closest('[data-cargo-parameter]');if(common){layout.cargoSpec??={length:1200,width:800,weight:100,unit:'mm'};const cargoKey=common.dataset.cargoParameter;layout.cargoSpec[cargoKey]=cargoKey==='weight'?Math.max(.01,Number(common.value)||.01):Math.max(1,Math.round(Number(common.value)||1));layout.cargoSpec.unit='mm';common.value=layout.cargoSpec[common.dataset.cargoParameter];resetEngine();return;}const input=event.target.closest('[data-equipment-id]');if(!input||input.readOnly)return;const item=layout.equipment.find(entry=>entry.id===input.dataset.equipmentId);if(item){item.parameters??={};const binary=['simultaneousMotion','returnHome','motionProfile'].includes(input.dataset.parameter),integer=binary||['levels','rows','columns','productTypes','stackerCount','releaseBatchSize','infeedColumn','infeedLevel','outfeedColumn','outfeedLevel'].includes(input.dataset.parameter),value=Number(input.value);item.parameters[input.dataset.parameter]=integer?Math.max(binary?0:1,Math.round(value||0)):value;if(input.dataset.parameter==='length')item.parameters.length=Math.max(.1,item.parameters.length||.1);if(input.dataset.parameter==='length'){item.source??={};item.source.parameterLengthUnit='m';}input.value=item.parameters[input.dataset.parameter];if(engine instanceof CadFlowEngine)engine.hotReloadEquipment(item);else resetEngine();renderer.draw(engine.state);if(['levels','rows','columns','productTypes','stackerCount'].includes(input.dataset.parameter))resetEngine();renderCadEquipmentParameters(item.id);}});
cadParameterSection.addEventListener('change',event=>{const input=event.target.closest('[data-equipment-id]');if(!input||!['speed','lineSpeed','travelSpeed','liftSpeed','receiveSpeed','transferSpeed','length','shuttleDistance','travelDistance','liftHeight','strokeDistance','columns','columnPitch'].includes(input.dataset.parameter))return;const item=layout.equipment.find(entry=>entry.id===input.dataset.equipmentId);if(!item||item.parameters?.autoMotionTuning===0)return;applyAutomaticMotionDynamics(item);if(engine instanceof CadFlowEngine)engine.hotReloadEquipment(item);else resetEngine();renderCadEquipmentParameters(item.id);});
cadParameterSection.addEventListener('change',event=>{const input=event.target.closest('[data-equipment-id]');if(!input||!['downSpeed','forkSpeed','forkStroke','levels','levelHeight'].includes(input.dataset.parameter))return;const item=layout.equipment.find(entry=>entry.id===input.dataset.equipmentId);if(!item||!['asrs','stackerCrane'].includes(item.type)||item.parameters?.autoMotionTuning===0)return;applyAutomaticMotionDynamics(item);if(engine instanceof CadFlowEngine)engine.hotReloadEquipment(item);else resetEngine();renderCadEquipmentParameters(item.id);});
cadParameterSection.addEventListener('click',event=>{const button=event.target.closest('[data-apply-equipment]');if(!button)return;const source=layout.equipment.find(entry=>entry.id===button.dataset.applyEquipment);if(!source)return;const keys=button.dataset.applyParameter?[button.dataset.applyParameter]:Object.keys(source.parameters||{});for(const target of layout.equipment.filter(entry=>entry.id!==source.id&&entry.type===source.type)){target.parameters??={};for(const key of keys)if(source.parameters?.[key]!==undefined)target.parameters[key]=structuredClone(source.parameters[key]);if(source.type==='conveyor'&&keys.includes('length')){target.source??={};target.source.parameterLengthUnit='m';}}resetEngine();renderCadEquipmentParameters(source.id);});
cadParameterSection.addEventListener('click',event=>{const button=event.target.closest('[data-fork-flow]');if(!button)return;const item=layout.equipment.find(entry=>entry.id===button.dataset.forkId);if(!item)return;const names=detectedFlowNames();item.parameters??={};const selected=new Set(Array.isArray(item.parameters.distributionFlowKeys)&&item.parameters.distributionFlowKeys.length?item.parameters.distributionFlowKeys:names);selected.has(button.dataset.forkFlow)?selected.delete(button.dataset.forkFlow):selected.add(button.dataset.forkFlow);item.parameters.distributionFlowKeys=[...selected];resetEngine();renderCadEquipmentParameters(item.id);});
$('cadCandidates').addEventListener('click',event=>{
  const button=event.target.closest('[data-cad-action]');if(!button)return;const action=button.dataset.cadAction,id=button.dataset.id;
  const selected=action==='approve-all'?pendingCadCandidates:pendingCadCandidates.filter(item=>item.id===id);
  if(action==='approve'||action==='approve-all'){
    const importId=selected[0]?.source?.importId;
    if(importId&&layout.cadActiveImportId!==importId){layout.equipment=layout.equipment.filter(item=>item.source?.origin!=='dxf');layout.cadActiveImportId=importId;layout.displayMode='cad';}
    for(const item of selected){item.reviewStatus='approved';layout.equipment.push(item);}
  }
  if(action==='approve-all'||action==='discard-all')pendingCadCandidates=[];else pendingCadCandidates=pendingCadCandidates.filter(item=>item.id!==id);
  renderer.setLayout(layout);if(action==='approve'||action==='approve-all')resetEngine();else renderer.draw(engine.state);renderCadCandidates();renderCadEquipmentParameters();
  if(action==='approve'||action==='approve-all'){$('cadStatusTitle').textContent='설비 반영 완료';$('cadStatusText').textContent=`${selected.length}개 설비를 레이아웃에 배치했습니다. 편집 모드에서 위치와 파라미터를 보정할 수 있습니다.`;}
  else if(action==='discard-all'){$('cadStatusTitle').textContent='후보 제외 완료';$('cadStatusText').textContent='분석 후보를 모두 제외했습니다.';}
});
document.querySelectorAll('[data-add]').forEach(button=>button.addEventListener('click',()=>editor.beginPlacement(button.dataset.add)));
$('newLayoutProject').addEventListener('click',()=>{layout=cloneLayout(emptyLayout);layout.id=`manual-${Date.now()}`;layout.name='새 물류 시뮬레이션';setProjectEmpty(false);renderer.setLayout(layout);$('editorTools').hidden=false;editor.setEnabled(true);$('editorToggle').textContent='편집 종료';resetEngine();renderCadEquipmentParameters();editor.fitView();});
$('connectEquipment').addEventListener('click',()=>{const active=!editor.connecting;editor.setConnectionMode(active);$('connectEquipment').classList.toggle('active',active);$('connectionHint').hidden=!active;$('connectionHint').textContent='시작 설비의 연결점을 누른 채 도착 설비 연결점까지 드래그하세요.';});
$('resetView').addEventListener('click',()=>editor.fitView());
$('deleteEquipment').addEventListener('click',()=>{if(selectedEquipment&&editor.remove(selectedEquipment.id)){resetEngine();renderCadEquipmentParameters();}});
$('deleteConnection').addEventListener('click',deleteSelectedConnection);$('contextDeleteConnection').addEventListener('click',deleteSelectedConnection);document.addEventListener('pointerdown',event=>{if(!event.target.closest('#edgeContextMenu')&&!event.target.closest('#layoutCanvas'))$('edgeContextMenu').hidden=true;});
for(const id of ['propName','propX','propY','propRotation']) $(id).addEventListener('change',()=>{if(!selectedEquipment)return;selectedEquipment.name=$('propName').value||selectedEquipment.name;selectedEquipment.x=Math.round(Number($('propX').value)||0);selectedEquipment.y=Math.round(Number($('propY').value)||0);selectedEquipment.rotation=((Number($('propRotation').value)||0)%360+360)%360;$('propX').value=selectedEquipment.x;$('propY').value=selectedEquipment.y;$('propRotation').value=selectedEquipment.rotation;refreshEquipmentConnections(layout,selectedEquipment.id);renderer.draw(engine.state);});
function rotateSelected(delta){if(!selectedEquipment)return;selectedEquipment.rotation=((Number(selectedEquipment.rotation)||0)+delta+360)%360;$('propRotation').value=selectedEquipment.rotation;refreshEquipmentConnections(layout,selectedEquipment.id);renderer.draw(engine.state);}
$('rotateLeft').addEventListener('click',()=>rotateSelected(-90));$('rotateRight').addEventListener('click',()=>rotateSelected(90));
$('layoutFile').addEventListener('change',async event=>{
  const file=event.target.files[0]; if(!file)return;
  try {const candidate=JSON.parse(await file.text()), check=validateLayout(candidate);if(!check.valid)throw new Error(check.errors.join(' '));layout=candidate;ensureCargoSpecMm(layout);writeParams(candidate.simulationParams);renderer.setLayout(layout);await renderer.setBackground(layout.background?.dataUrl||null);setProjectEmpty(false);resetEngine();renderCadEquipmentParameters();$('layoutName').textContent=layout.name;selectEquipment(null);editor.fitView();}
  catch(error){$('validation').textContent='레이아웃 불러오기 실패: '+error.message;} finally{event.target.value='';}
});
writeParams(defaultParams);setProjectEmpty(true);syncFlowView();renderer.draw({t:0,cadTokens:[],source:[],product:[],locks:{},robot:{phase:'idle'}});renderEvents();
